create or replace function public.is_organization_member(target_organization uuid) returns boolean language sql security definer set search_path = public as $$ select exists (select 1 from public.memberships m where m.organization_id = target_organization and m.user_id = auth.uid() and m.left_at is null); $$;
create or replace function public.is_school_director(target_organization uuid) returns boolean language sql security definer set search_path = public as $$ select exists (select 1 from public.memberships m where m.organization_id = target_organization and m.user_id = auth.uid() and m.role = 'director' and m.left_at is null); $$;
create or replace function public.is_super_admin() returns boolean language sql security definer set search_path = public as $$ select exists (select 1 from public.profiles p where p.id = auth.uid() and p.role = 'super_admin'); $$;
create or replace function public.is_referential_admin() returns boolean language sql security definer set search_path = public as $$ select exists (select 1 from public.profiles p where p.id = auth.uid() and p.role = 'referential_admin'); $$;
create or replace function public.assert_organization_member(target_organization uuid) returns void language plpgsql security definer set search_path = public as $$ begin if not public.is_organization_member(target_organization) then raise exception 'Accès refusé.'; end if; end; $$;
create or replace function public.assert_director_or_super(target_organization uuid) returns void language plpgsql security definer set search_path = public as $$ begin if not (public.is_super_admin() or public.is_school_director(target_organization)) then raise exception 'Accès refusé.'; end if; end; $$;
create or replace function public.assert_super_admin() returns void language plpgsql security definer set search_path = public as $$ begin if not public.is_super_admin() then raise exception 'Accès refusé.'; end if; end; $$;
